00054 PriorityMap::TileGrid::TileGrid(const Surface &surface, unsigned tile_size_x, unsigned tile_size_y)
00055     : tile_size_x_{tile_size_x}, tile_size_y_{tile_size_y} {
00056 
00057     n_tiles_x_ = surface.width() / tile_size_x;
00058     if (n_tiles_x_ * tile_size_x < surface.width()) {
00059         n_tiles_x_++;
00060     }
00061 
00062     n_tiles_y_ = surface.height() / tile_size_y;
00063     if (n_tiles_y_ * tile_size_y < surface.height()) {
00064         n_tiles_y_++;
00065     }
00066 }
00067 
00068 PriorityMap::TileGrid::TileGrid(unsigned tile_size_x, unsigned tile_size_y, unsigned n_tiles_x, unsigned n_tiles_y)
00069     : tile_size_x_{tile_size_x}, tile_size_y_{tile_size_y}, n_tiles_x_{n_tiles_x}, n_tiles_y_{n_tiles_y} {}
00070 
00071 std::array<PriorityMap::pmap_function, 3> PriorityMap::priority_functions_ = {&kill_all_residuals, &keep_all_residuals,
00072                                                                               &threshold_cutoff};
00073 
00074 // For each block in map - kill coefficients if corresponding block is set to 0 in map
00075 Surface PriorityMap::process(const Surface &src_plane, unsigned priority_tile_x, unsigned priority_tile_y,
00076                              KillingFunction killing_function) {
00077     assert(0 <= killing_function);
00078     assert(killing_function < priority_functions_.size());
00079 
00080     const TileGrid grid{src_plane, priority_tile_x, priority_tile_y};
00081 
00082     // Store priority values in raster order
00083     // This implementation uses a hardcoded 'dummy' value - should
00084     // be replaced by a more sophisticated algorithm
00085     std::vector<double> pvalues(grid.n_tiles_x_ * grid.n_tiles_y_);
00086 
00087     for (unsigned tile_y = 0; tile_y < grid.n_tiles_y_; ++tile_y) {
00088         for (unsigned tile_x = 0; tile_x < grid.n_tiles_x_; ++tile_x) {
00089 
00090             pvalues[tile_y * grid.n_tiles_x_ + tile_x] = 0.7;
00091         }
00092     }
00093 
00094     return priority_functions_[killing_function](src_plane, pvalues, grid);
00095 }
00096 
00097 Surface PriorityMap::kill_all_residuals(const Surface &src_surface, const std::vector<double> &priority_values,
00098                                         const TileGrid &tgrid) {
00099     return Surface::build_from<value_type>()
00100         .generate(src_surface.width(), src_surface.height(),
00101                   [](unsigned x, unsigned y) -> value_type { return ResidualLabel::RESIDUAL_KILL; })
00102         .finish();
00103 }
00104 
00105 Surface PriorityMap::keep_all_residuals(const Surface &src_surface, const std::vector<double> &priority_values,
00106                                         const TileGrid &tgrid) {
00107     return Surface::build_from<value_type>()
00108         .generate(src_surface.width(), src_surface.height(),
00109                   [](unsigned x, unsigned y) -> value_type { return ResidualLabel::RESIDUAL_LIVE; })
00110         .finish();
00111 }
00112 
00113 Surface PriorityMap::threshold_cutoff(const Surface &src_surface, const std::vector<double> &priority_values,
00114                                       const TileGrid &tgrid) {
00115 
00116     const double T = 0.5;
00117     const auto threshold_kill_function = [T](const double priority) -> value_type {
00118         return (priority > T) ? ResidualLabel::RESIDUAL_LIVE : ResidualLabel::RESIDUAL_KILL;
00119     };
00120 
00121     Surface pixel_priority_map =
00122         Surface::build_from<value_type>()
00123             .generate(src_surface.width(), src_surface.height(),
00124                       [priority_values, tgrid, threshold_kill_function](unsigned x, unsigned y) -> value_type {
00125                           const auto tile_x = x / tgrid.tile_size_x_;
00126                           const auto tile_y = y / tgrid.tile_size_y_;
00127                           const auto priority_value = priority_values[tile_y * tgrid.n_tiles_x_ + tile_x];
00128                           const auto priority_label = threshold_kill_function(priority_value);
00129                           return priority_label;
00130                       })
00131             .finish();
00132     return pixel_priority_map;
00133 }
00134 
00135 Surface PriorityMapVis::process(const Surface &src_plane) {
00136     // Read-only access to source surface
00137     constexpr auto scale_factor = std::numeric_limits<int16_t>::max() / std::numeric_limits<uint8_t>::max();
00138 
00139     const auto src_plane_view = src_plane.view_as<int16_t>();
00140     Surface rescaled_priority_map =
00141         Surface::build_from<int16_t>()
00142             .generate(src_plane.width(), src_plane.height(),
00143                       [scale_factor, &src_plane_view](unsigned x, unsigned y) -> int16_t {
00144                           const auto rescaled_value = static_cast<int16_t>(std::round(src_plane_view.read(x, y) * scale_factor));
00145                           return rescaled_value;
00146                       })
00147             .finish();
00148     return rescaled_priority_map;
00149 }
00150 
00151 Surface PriorityMap::ComputeMeanValue(const Surface &src_surface) {
00152     const auto src_view = src_surface.view_as<int16_t>();
00153     auto mean = Surface::build_from<uint8_t>();
00154     mean.reserve((src_surface.width() + BLOCK_SIZE - 1) / BLOCK_SIZE, (src_surface.height() + BLOCK_SIZE - 1) / BLOCK_SIZE);
00155     for (unsigned y = 0; y < src_surface.height(); y += BLOCK_SIZE) {
00156         for (unsigned x = 0; x < src_surface.width(); x += BLOCK_SIZE) {
00157             int acc = 0;
00158             unsigned maxk = LCEVC_MIN(BLOCK_SIZE, src_surface.height() - y);
00159             unsigned maxh = LCEVC_MIN(BLOCK_SIZE, src_surface.width() - x);
00160             for (unsigned k = 0; k < maxk; k++) {
00161                 for (unsigned h = 0; h < maxh; h++) {
00162                     // for both 8 bpp and 10 bpp, work with averages of 8 bpp values
00163                     acc += (src_view.read(x + h, y + k) >> 7);
00164                 }
00165             }
00166             acc = acc / (BLOCK_SIZE * BLOCK_SIZE);
00167             mean.write(x / BLOCK_SIZE, y / BLOCK_SIZE, clamp(acc, 0, 255));
00168         }
00169     }
00170     return mean.finish();
00171 }
00172 
00173 Surface PriorityMap::ComputeContrastTexture(const Surface &src_surface, Surface &mean_surface) {
00174     const auto src_view = src_surface.view_as<int16_t>();
00175     const auto mean_view = mean_surface.view_as<uint8_t>();
00176     auto type = Surface::build_from<uint8_t>();
00177     type.reserve((src_surface.width() + BLOCK_SIZE - 1) / BLOCK_SIZE, (src_surface.height() + BLOCK_SIZE - 1) / BLOCK_SIZE);
00178 
00179     const float textureThreshold = 0.15f;  // 0.15f
00180     const float contrastThreshold = 0.10f; // 0.10f
00181 
00182     for (unsigned y = 0; y < src_surface.height(); y += BLOCK_SIZE) {
00183         for (unsigned x = 0; x < src_surface.width(); x += BLOCK_SIZE) {
00184             int crossings = 0;
00185             int mean = mean_view.read(x / BLOCK_SIZE, y / BLOCK_SIZE);
00186             int accLo = 0, numLo = 0;
00187             int accHi = 0, numHi = 0;
00188             unsigned maxk = LCEVC_MIN(BLOCK_SIZE, src_surface.height() - y);
00189             unsigned maxh = LCEVC_MIN(BLOCK_SIZE, src_surface.width() - x);
00190             for (unsigned k = 0; k < maxk; k++) {
00191                 for (unsigned h = 0; h < maxh; h++) {
00192                     // X = current; L = left (x-1); U = up (y-1);
00193                     int pixelX = src_view.read(x + h, y + k) >> 7;
00194 
00195                     // CONTRAST = difference in high/low mean values
00196                     if (pixelX <= mean) {
00197                         accLo += pixelX;
00198                         numLo++;
00199                     } else {
00200                         accHi += pixelX;
00201                         numHi++;
00202                     }
00203 
00204                     if (y > 0) {
00205                         int pixelU = src_view.read(x + h, y + k - 1) >> 7;
00206                         // TEXTURE = number of crossings
00207                         // horizontal egde -- UP delta
00208                         if ((pixelX > mean && pixelU <= mean) || (pixelX <= mean && pixelU > mean))
00209                             crossings += (abs(pixelX - pixelU) > 4);
00210                     }
00211                     if (x > 0) {
00212                         int pixelL = src_view.read(x + h - 1, y + k) >> 7;
00213                         // TEXTURE = number of crossings
00214                         // vertical edge -- LEFT delta
00215                         if ((pixelX > mean && pixelL <= mean) || (pixelX <= mean && pixelL > mean))
00216                             crossings += (abs(pixelX - pixelL) > 4);
00217                     }
00218                 }
00219             }
00220             float meanLo = 0.0f;
00221             float meanHi = 0.0f;
00222             if (numLo > 0 && numHi > 0) {
00223                 meanLo = (float)accLo / numLo;
00224                 meanHi = (float)accHi / numHi;
00225             }
00226             float contrast = (meanHi - meanLo) / 255.0f;
00227             float texture = (float)(crossings) / (2 * BLOCK_SIZE * (BLOCK_SIZE - 1));
00228 
00229             EnumBlockType blockType = EnumBlockType::Plain;
00230             if (texture <= textureThreshold) {
00231                 // if TEXTURE is "small" classify for CONTRAST
00232                 if (contrast <= contrastThreshold)
00233                     blockType = EnumBlockType::Plain;
00234                 else
00235                     blockType = EnumBlockType::Edge;
00236             } else {
00237                 // if TEXTURE is "large" classify for TEXTURE
00238                 if (contrast <= contrastThreshold)
00239                     blockType = EnumBlockType::SmoothTexture;
00240                 else
00241                     blockType = EnumBlockType::CoarseTexture;
00242 
00243                 if ((blockType == EnumBlockType::SmoothTexture) && (contrast <= 0.02f)) {
00244                     blockType = EnumBlockType::Plain;
00245                 }
00246             }
00247             type.write(x / BLOCK_SIZE, y / BLOCK_SIZE, (uint8_t)blockType);
00248         }
00249     }
00250     return type.finish();
00251 }
00252 
00253 // NEED REVISITATION FOR SL-2 TO INCLUDE ADDITIONAL PM TYPE AND MODE
00254 Surface PriorityMap::ApplyPriorityResiduals(Surface &src_surface, Surface &type_surface, unsigned step_width) {
00255     const auto src_view = src_surface.view_as<int16_t>();
00256     const auto type_view = type_surface.view_as<uint8_t>();
00257     auto dest = Surface::build_from<int16_t>();
00258     dest.reserve(src_surface.width(), src_surface.height());
00259     EnumBlockType blockType = EnumBlockType::Plain;
00260 
00261     for (unsigned y = 0; y < src_surface.height(); y += BLOCK_SIZE) {
00262         for (unsigned x = 0; x < src_surface.width(); x += BLOCK_SIZE) {
00263             blockType = (EnumBlockType)type_view.read(x / BLOCK_SIZE, y / BLOCK_SIZE);
00264             unsigned maxk = LCEVC_MIN(BLOCK_SIZE, src_surface.height() - y);
00265             unsigned maxh = LCEVC_MIN(BLOCK_SIZE, src_surface.width() - x);
00266             if (blockType == EnumBlockType::Plain || (blockType == EnumBlockType::CoarseTexture && step_width > 300)) {
00267                 for (unsigned k = 0; k < maxk; k++) {
00268                     for (unsigned h = 0; h < maxh; h++) {
00269                         dest.write(x + h, y + k, 0);
00270                     }
00271                 }
00272             } else {
00273                 for (unsigned k = 0; k < maxk; k++) {
00274                     for (unsigned h = 0; h < maxh; h++) {
00275                         dest.write(x + h, y + k, src_view.read(x + h, y + k));
00276                     }
00277                 }
00278             }
00279         }
00280     }
00281     return dest.finish();
00282 }
00283 
00284 void PriorityMap::ApplyPriorityCoefficients(int width, int height, int tu_size, int sublayer, Surface src_surface[],
00285                                             Surface dst_surface[], const Surface &type_surface, const Surface &pixel_sad,
00286                                             unsigned step_width, PriorityMBType priority_mb_type, EncodingMode mode) {
00287     const bool sad = !pixel_sad.empty();
00288     if (tu_size == 4) {
00289         // case 4x4
00290         const auto src00_view = src_surface[0].view_as<int16_t>();
00291         const auto src01_view = src_surface[1].view_as<int16_t>();
00292         const auto src02_view = src_surface[2].view_as<int16_t>();
00293         const auto src03_view = src_surface[3].view_as<int16_t>();
00294         const auto src04_view = src_surface[4].view_as<int16_t>();
00295         const auto src05_view = src_surface[5].view_as<int16_t>();
00296         const auto src06_view = src_surface[6].view_as<int16_t>();
00297         const auto src07_view = src_surface[7].view_as<int16_t>();
00298         const auto src08_view = src_surface[8].view_as<int16_t>();
00299         const auto src09_view = src_surface[9].view_as<int16_t>();
00300         const auto src10_view = src_surface[10].view_as<int16_t>();
00301         const auto src11_view = src_surface[11].view_as<int16_t>();
00302         const auto src12_view = src_surface[12].view_as<int16_t>();
00303         const auto src13_view = src_surface[13].view_as<int16_t>();
00304         const auto src14_view = src_surface[14].view_as<int16_t>();
00305         const auto src15_view = src_surface[15].view_as<int16_t>();
00306         const auto pixel_sad_view = (sad ? pixel_sad.view_as<int16_t>() : src_surface[0].view_as<int16_t>());
00307         auto dest00 = Surface::build_from<int16_t>();
00308         dest00.reserve(width, height);
00309         auto dest01 = Surface::build_from<int16_t>();
00310         dest01.reserve(width, height);
00311         auto dest02 = Surface::build_from<int16_t>();
00312         dest02.reserve(width, height);
00313         auto dest03 = Surface::build_from<int16_t>();
00314         dest03.reserve(width, height);
00315         auto dest04 = Surface::build_from<int16_t>();
00316         dest04.reserve(width, height);
00317         auto dest05 = Surface::build_from<int16_t>();
00318         dest05.reserve(width, height);
00319         auto dest06 = Surface::build_from<int16_t>();
00320         dest06.reserve(width, height);
00321         auto dest07 = Surface::build_from<int16_t>();
00322         dest07.reserve(width, height);
00323         auto dest08 = Surface::build_from<int16_t>();
00324         dest08.reserve(width, height);
00325         auto dest09 = Surface::build_from<int16_t>();
00326         dest09.reserve(width, height);
00327         auto dest10 = Surface::build_from<int16_t>();
00328         dest10.reserve(width, height);
00329         auto dest11 = Surface::build_from<int16_t>();
00330         dest11.reserve(width, height);
00331         auto dest12 = Surface::build_from<int16_t>();
00332         dest12.reserve(width, height);
00333         auto dest13 = Surface::build_from<int16_t>();
00334         dest13.reserve(width, height);
00335         auto dest14 = Surface::build_from<int16_t>();
00336         dest14.reserve(width, height);
00337         auto dest15 = Surface::build_from<int16_t>();
00338         dest15.reserve(width, height);
00339         const auto type_view = type_surface.view_as<uint8_t>();
00340         EnumBlockType blockType = EnumBlockType::Plain;
00341         if (sublayer == LOQ_LEVEL_1) {
00342             for (unsigned y = 0; y < (unsigned)height; y++) {
00343                 for (unsigned x = 0; x < (unsigned)width; x++) {
00344 
00345                     if (mode != EncodingMode::ENCODE_ALL)
00346                     {
00347                         blockType = (EnumBlockType)type_view.read((x * 4) / (BLOCK_SIZE), (y * 4) / (BLOCK_SIZE));
00348 
00349                         bool keepAverage = false;
00350 
00351                         //Decision type
00352                         switch (priority_mb_type)
00353                         {
00354                             case PriorityMBType::SmoothAndPlain: // Keep smooth and plain
00355                                 keepAverage = (blockType == EnumBlockType::Plain || blockType == EnumBlockType::SmoothTexture);
00356                                 break;
00357                         
00358                             case PriorityMBType::CoarseAndPlain: // Remove coarse and plain
00359                                 keepAverage = (blockType == EnumBlockType::Plain || blockType == EnumBlockType::CoarseTexture);
00360                                 break;
00361 
00362                             case PriorityMBType::Smooth: // Keep smooth only
00363                                 keepAverage = (blockType == EnumBlockType::SmoothTexture);
00364                                 break;
00365                         
00366                             case PriorityMBType::Plain: // Keep plain only
00367                                 keepAverage = (blockType == EnumBlockType::Plain);
00368                                 break;
00369                             
00370                             case PriorityMBType::Coarse: // Keep coarse only
00371                                 keepAverage = (blockType == EnumBlockType::CoarseTexture);
00372                                 break;
00373 
00374                             case PriorityMBType::Edge: // Keep Edges only
00375                                 keepAverage = (blockType == EnumBlockType::Edge);
00376                                 break;
00377                         
00378                             default: break;
00379                         }
00380 
00381                         // layer1 -- keep average
00382                         if (keepAverage)
00383                         {
00384                             switch (mode)
00385                             {
00386                                 case EncodingMode::Ax: // Keep all average
00387                                 {
00388                                     dest00.write(x, y, src00_view.read(x, y));
00389                                     dest01.write(x, y, src01_view.read(x, y));
00390                                     dest02.write(x, y, src02_view.read(x, y));
00391                                     dest03.write(x, y, src03_view.read(x, y));
00392                                 }
00393                                 break;
00394                                 case EncodingMode::AA: // Keep only AA
00395                                 {
00396                                     dest00.write(x, y, src00_view.read(x, y));
00397                                     dest01.write(x, y, 0);
00398                                     dest02.write(x, y, 0);
00399                                     dest03.write(x, y, 0);
00400                                 }
00401                                 break;
00402                                 case EncodingMode::NA: // Keep AV, AH and AD
00403                                 {
00404                                     dest00.write(x, y, 0);
00405                                     dest01.write(x, y, src01_view.read(x, y));
00406                                     dest02.write(x, y, src02_view.read(x, y));
00407                                     dest03.write(x, y, src03_view.read(x, y));
00408                                 }
00409                                 break;
00410                                 default: break;
00411                             }
00412                         }
00413                         else
00414                         {
00415                             dest00.write(x, y, 0);
00416                             dest01.write(x, y, 0);
00417                             dest02.write(x, y, 0);
00418                             dest03.write(x, y, 0);
00419                         }
00420                         dest04.write(x, y, 0);
00421                         dest05.write(x, y, 0);
00422                         dest06.write(x, y, 0);
00423                         dest07.write(x, y, 0);
00424                         dest08.write(x, y, 0);
00425                         dest09.write(x, y, 0);
00426                         dest10.write(x, y, 0);
00427                         dest11.write(x, y, 0);
00428                         dest12.write(x, y, 0);
00429                         dest13.write(x, y, 0);
00430                         dest14.write(x, y, 0);
00431                         dest15.write(x, y, 0);
00432                     }
00433                     else
00434                     {
00435                         dest00.write(x, y, src00_view.read(x, y));
00436                         dest01.write(x, y, src01_view.read(x, y));
00437                         dest02.write(x, y, src02_view.read(x, y));
00438                         dest03.write(x, y, src03_view.read(x, y));
00439                         dest04.write(x, y, src04_view.read(x, y));
00440                         dest05.write(x, y, src05_view.read(x, y));
00441                         dest06.write(x, y, src06_view.read(x, y));
00442                         dest07.write(x, y, src07_view.read(x, y));
00443                         dest08.write(x, y, src08_view.read(x, y));
00444                         dest09.write(x, y, src09_view.read(x, y));
00445                         dest10.write(x, y, src10_view.read(x, y));
00446                         dest11.write(x, y, src11_view.read(x, y));
00447                         dest12.write(x, y, src12_view.read(x, y));
00448                         dest13.write(x, y, src13_view.read(x, y));
00449                         dest14.write(x, y, src14_view.read(x, y));
00450                         dest15.write(x, y, src15_view.read(x, y));
00451                     }
00452                     
00453                 } // for x
00454             } // for y
00455         } 
00456         else if (sublayer == LOQ_LEVEL_2)
00457         {
00458             for (unsigned y = 0; y < (unsigned)height; y++) {
00459                 for (unsigned x = 0; x < (unsigned)width; x++) {
00460                     blockType = (EnumBlockType)type_view.read((x * 4) / (BLOCK_SIZE), (y * 4) / (BLOCK_SIZE));
00461 
00462                     bool removeCoeff = false;
00463 
00464                     // Only apply priority map if block is non-static
00465                     if (sad && pixel_sad_view.read(x, y) > 1000) {
00466                         // Decision type
00467                         switch (priority_mb_type) {
00468                         case PriorityMBType::SmoothAndPlain: // Remove smooth and plain
00469                             removeCoeff = (blockType == EnumBlockType::Plain ||
00470                                            (blockType == EnumBlockType::SmoothTexture && step_width > 300));
00471                             break;
00472 
00473                         case PriorityMBType::CoarseAndPlain: // Remove coarse and plain
00474                             removeCoeff = (blockType == EnumBlockType::Plain ||
00475                                            (blockType == EnumBlockType::CoarseTexture && step_width > 300));
00476                             break;
00477 
00478                         case PriorityMBType::Smooth: // Remove smooth only
00479                             removeCoeff = (blockType == EnumBlockType::SmoothTexture && step_width > 300);
00480                             break;
00481 
00482                         case PriorityMBType::Plain: // Remove plain only
00483                             removeCoeff = (blockType == EnumBlockType::Plain);
00484                             break;
00485 
00486                         case PriorityMBType::Coarse: // Remove coarse only
00487                             removeCoeff = (blockType == EnumBlockType::CoarseTexture && step_width > 300);
00488                             break;
00489 
00490                         case PriorityMBType::Edge: // Remove Edges only
00491                             removeCoeff = (blockType == EnumBlockType::Edge);
00492                             break;
00493 
00494                         default:
00495                             break;
00496                         }
00497                     }
00498 
00499                     if (removeCoeff) {
00500                         // layer2 -- plain or coarse_texture
00501                         dest00.write(x, y, 0);
00502                         dest01.write(x, y, 0);
00503                         dest02.write(x, y, 0);
00504                         dest03.write(x, y, 0);
00505                         dest04.write(x, y, 0);
00506                         dest05.write(x, y, 0);
00507                         dest06.write(x, y, 0);
00508                         dest07.write(x, y, 0);
00509                         dest08.write(x, y, 0);
00510                         dest09.write(x, y, 0);
00511                         dest10.write(x, y, 0);
00512                         dest11.write(x, y, 0);
00513                         dest12.write(x, y, 0);
00514                         dest13.write(x, y, 0);
00515                         dest14.write(x, y, 0);
00516                         dest15.write(x, y, 0);
00517                     } else {
00518                         // layer2 -- edge or smooth_texture
00519                         dest00.write(x, y, src00_view.read(x, y));
00520                         dest01.write(x, y, src01_view.read(x, y));
00521                         dest02.write(x, y, src02_view.read(x, y));
00522                         dest03.write(x, y, src03_view.read(x, y));
00523                         dest04.write(x, y, src04_view.read(x, y));
00524                         dest05.write(x, y, src05_view.read(x, y));
00525                         dest06.write(x, y, src06_view.read(x, y));
00526                         dest07.write(x, y, src07_view.read(x, y));
00527                         dest08.write(x, y, src08_view.read(x, y));
00528                         dest09.write(x, y, src09_view.read(x, y));
00529                         dest10.write(x, y, src10_view.read(x, y));
00530                         dest11.write(x, y, src11_view.read(x, y));
00531                         dest12.write(x, y, src12_view.read(x, y));
00532                         dest13.write(x, y, src13_view.read(x, y));
00533                         dest14.write(x, y, src14_view.read(x, y));
00534                         dest15.write(x, y, src15_view.read(x, y));
00535                     }
00536                 } // for x
00537             }     // for y
00538         }
00539         dst_surface[0] = dest00.finish();
00540         dst_surface[1] = dest01.finish();
00541         dst_surface[2] = dest02.finish();
00542         dst_surface[3] = dest03.finish();
00543         dst_surface[4] = dest04.finish();
00544         dst_surface[5] = dest05.finish();
00545         dst_surface[6] = dest06.finish();
00546         dst_surface[7] = dest07.finish();
00547         dst_surface[8] = dest08.finish();
00548         dst_surface[9] = dest09.finish();
00549         dst_surface[10] = dest10.finish();
00550         dst_surface[11] = dest11.finish();
00551         dst_surface[12] = dest12.finish();
00552         dst_surface[13] = dest13.finish();
00553         dst_surface[14] = dest14.finish();
00554         dst_surface[15] = dest15.finish();
00555     } else if (tu_size == 2) {
00556         // case 2x2
00557         const auto src00_view = src_surface[0].view_as<int16_t>();
00558         const auto src01_view = src_surface[1].view_as<int16_t>();
00559         const auto src02_view = src_surface[2].view_as<int16_t>();
00560         const auto src03_view = src_surface[3].view_as<int16_t>();
00561         const auto pixel_sad_view = (sad ? pixel_sad.view_as<int16_t>() : src_surface[0].view_as<int16_t>());
00562         auto dest00 = Surface::build_from<int16_t>();
00563         dest00.reserve(width, height);
00564         auto dest01 = Surface::build_from<int16_t>();
00565         dest01.reserve(width, height);
00566         auto dest02 = Surface::build_from<int16_t>();
00567         dest02.reserve(width, height);
00568         auto dest03 = Surface::build_from<int16_t>();
00569         dest03.reserve(width, height);
00570         const auto type_view = type_surface.view_as<uint8_t>();
00571         EnumBlockType blockType = EnumBlockType::Plain;
00572         if (sublayer == LOQ_LEVEL_1) {
00573             for (unsigned y = 0; y < (unsigned)height; y++) {
00574                 for (unsigned x = 0; x < (unsigned)width; x++) {
00575                     blockType = (EnumBlockType)type_view.read((x * 2) / (BLOCK_SIZE), (y * 2) / (BLOCK_SIZE));
00576 
00577                     bool keepAverage = false;
00578                     
00579                     switch (priority_mb_type)
00580                     {
00581                         case PriorityMBType::SmoothAndPlain: // Keep smooth and plain
00582                             keepAverage = (blockType == EnumBlockType::Plain || blockType == EnumBlockType::SmoothTexture);
00583                             break;
00584                     
00585                         case PriorityMBType::CoarseAndPlain: // Remove coarse and plain
00586                             keepAverage = (blockType == EnumBlockType::Plain || blockType == EnumBlockType::CoarseTexture);
00587                             break;
00588                     
00589                         case PriorityMBType::Smooth: // Keep smooth only
00590                             keepAverage = (blockType == EnumBlockType::SmoothTexture);
00591                             break;
00592                     
00593                         case PriorityMBType::Plain: // Keep plain only
00594                             keepAverage = (blockType == EnumBlockType::Plain);
00595                             break;
00596                         
00597                         case PriorityMBType::Coarse: // Keep coarse only
00598                             keepAverage = (blockType == EnumBlockType::CoarseTexture);
00599                             break;
00600                     
00601                         case PriorityMBType::Edge: // Keep Edges only
00602                             keepAverage = (blockType == EnumBlockType::Edge);
00603                             break;
00604                     
00605                         default: break;
00606                     }
00607                     
00608                     // layer1 -- keep average
00609                     if (keepAverage) {
00610                         dest00.write(x, y, src00_view.read(x, y));
00611                     } else {
00612                         dest00.write(x, y, 0);
00613                     }
00614                     dest01.write(x, y, 0);
00615                     dest02.write(x, y, 0);
00616                     dest03.write(x, y, 0);
00617                 } // for x
00618             }     // for y
00619         } else if (sublayer == LOQ_LEVEL_2) {
00620             for (unsigned y = 0; y < (unsigned)height; y++) {
00621                 for (unsigned x = 0; x < (unsigned)width; x++) {
00622                     blockType = (EnumBlockType)type_view.read((x * 2) / (BLOCK_SIZE), (y * 2) / (BLOCK_SIZE));
00623 
00624                     bool removeCoeff = false;
00625 
00626                     // Only apply priority map if block is non-static
00627                     if (step_width > 300 && sad && pixel_sad_view.read(x, y) > 500) {
00628                         // Decision type
00629                         switch (priority_mb_type) {
00630                         case PriorityMBType::SmoothAndPlain: // Remove smooth and plain
00631                             removeCoeff = (blockType == EnumBlockType::Plain ||
00632                                            (blockType == EnumBlockType::SmoothTexture && step_width > 300));
00633                             break;
00634 
00635                         case PriorityMBType::CoarseAndPlain: // Remove coarse and plain
00636                             removeCoeff = (blockType == EnumBlockType::Plain ||
00637                                            (blockType == EnumBlockType::CoarseTexture && step_width > 300));
00638                             break;
00639 
00640                         case PriorityMBType::Smooth: // Remove smooth only
00641                             removeCoeff = (blockType == EnumBlockType::SmoothTexture && step_width > 300);
00642                             break;
00643 
00644                         case PriorityMBType::Plain: // Remove plain only
00645                             removeCoeff = (blockType == EnumBlockType::Plain);
00646                             break;
00647 
00648                         case PriorityMBType::Coarse: // Remove coarse only
00649                             removeCoeff = (blockType == EnumBlockType::CoarseTexture && step_width > 300);
00650                             break;
00651 
00652                         case PriorityMBType::Edge: // Remove Edges only
00653                             removeCoeff = (blockType == EnumBlockType::Edge);
00654                             break;
00655 
00656                         default:
00657                             break;
00658                         }
00659                     }
00660 
00661                     if (removeCoeff) {
00662                         // layer2 -- plain or coarse_texture
00663                         dest00.write(x, y, 0);
00664                         dest01.write(x, y, 0);
00665                         dest02.write(x, y, 0);
00666                         dest03.write(x, y, 0);
00667                     } else {
00668                         // layer2 -- edge or smooth_texture
00669                         dest00.write(x, y, src00_view.read(x, y));
00670                         dest01.write(x, y, src01_view.read(x, y));
00671                         dest02.write(x, y, src02_view.read(x, y));
00672                         dest03.write(x, y, src03_view.read(x, y));
00673                     }
00674                 } // for x
00675             }     // for y
00676         }
00677         dst_surface[0] = dest00.finish();
00678         dst_surface[1] = dest01.finish();
00679         dst_surface[2] = dest02.finish();
00680         dst_surface[3] = dest03.finish();
00681     } // tu_size = 4 or 2
00682     
00683     return;
00684 }
00685 
00686 void StaticResiduals::process(Surface src_coeffs[], Surface dst_coeffs[], const Surface &pixel_sad_plane, unsigned num_layers,
00687                               unsigned step_width, unsigned sad_threshold, unsigned sad_coeff_threshold) {
00688     const auto pixel_sad = pixel_sad_plane.view_as<int16_t>();
00689 
00690     for (unsigned layer = 0; layer < num_layers; ++layer) {
00691         const auto src_view = src_coeffs[layer].view_as<int16_t>();
00692         dst_coeffs[layer] = Surface::build_from<int16_t>()
00693                                 .generate(src_view.width(), src_view.height(),
00694                                           [&](unsigned x, unsigned y) -> int16_t {
00695                                               if ((unsigned)pixel_sad.read(x, y) >= sad_threshold) {
00696                                                   return (unsigned)std::abs(src_view.read(x, y)) > sad_coeff_threshold * step_width
00697                                                              ? src_view.read(x, y)
00698                                                              : 0;
00699                                               } else {
00700                                                   return src_view.read(x, y);
00701                                               }
00702                                           })
00703                                 .finish();
00704     }
00705 }
